budget = int(input())
def best_value(budget):
    best = 0
    for a in range(budget // 3 + 1):
        for b in range(budget // 4 + 1):
            if a * 3 + b * 4 <= budget:
                value = a * 5 + b * 7
                if value > best:
                    best = value
    return best
